+void TextureStorage::decal_instance_free(RID p_decal_instance) {
+	DecalInstance *di = decal_instance_owner.get_or_null(p_decal_instance);
+	free_decal_id(di->decal_id);
+	decal_instance_owner.free(p_decal_instance);
+}
